;Реплики на какие-либо события (применение вещей);Длина строки 42 символаRUS=1REPLICSM=-REPLIC+PL        DW RP0+SM,RP1+SM,RP2+SM,RP3+SM,RP4+SM,RP5+SM,RP6+SM        DW RP7+SM,RP8+SM,RP9+SM,RP10+SM,RP11+SM,RP12+SM        DW RP13+SM,RP14+SM,RP15+SM,RP16+SM,RP17+SM,RP18+SM        DW RP19+SM,RP20+SM,RP21+SM,RP22+SM,RP23+SM,RP24+SM        DW RP25+SM,RP26+SM,RP27+SM,RP28+SM,RP29+SM,RP30+SM        DW RP31+SM        if RUSRP0     DB "В одно прекрасное утро в домик колдуньи",CR        DB "Веры кто-то постучался. Она слезла с печи,",CR        DB "оделась и открыла дверь. На пороге лежало",CR        DB "письмо...",END        elseRP0     DB "One fine morning someone knocked on the",CR        DB "house of the sorceress Vera. She got off",CR        DB "the stove, dressed and opened the door.",CR        DB "There was a letter on the doorstep...",END        endifRP1     DB "Развернув письмо, Вера прочла следующее:",CR        DB """Ясная поляна"" в опасности. Нам нужна",CR        DB "ваша помощь. Старейшина Хевор",SCRPT,1RP2     DB "Оседлав метлу и сказав заклинание, Вера",CR        DB "тотчас оказалась на другой стороне болота.",SCRPT,3RP3     DB "Живая вода, весело журча, наполнила",CR        DB "флакон.",SCRPT,5RP4     DB "Как только Вера выплеснула содержимое",CR        DB "флакона на козленка, он тут же обрел",CR        DB "человеческий облик.",SCRPT,6RP5     DB "Ведро с грохотом полетело в колодец,",CR        DB "а назад вернулось полное чистейшей воды.",SCRPT,9RP6     DB "Хм... Фонтан работает. А как он работает -",CR        DB "не важно...",SCRPT,10RP7     DB "Серпом Вера срезала небольшую охапку",CR        DB "колосьев пшеницы.",SCRPT,CRRP8     DB "Серпом Вера срезала небольшой пучок хмеля.",SCRPT,14RP9     DB "Вера вновь попыталась использовать серп,",CR        DB "но он был туп и уже ни на что не годился.",ENDRP10    DB "Хорошо, что мама научила меня обращаться",CR        DB "с пчелами, подумала Вера, набирая мед",CR        DB "в пустой флакон.",SCRPT,20RP11    DB "Немного поработав лезвием, Вера срезала",CR        DB "небольшую охапку колосьев пшеницы.",SCRPT,17RP12    DB "С помощью лезвия, Вера срезала небольшой",CR        DB "пучок хмеля.",SCRPT,18RP13    DB "Использовать лезвие не удалось, так как",CR        DB "оно затупилось.",ENDRP14    DB "Размахнувшись увесистым топором, Вера",CR        DB "ударила по скелету...",SCRPT,34RP15    DB "На мельнице Вере удалось обменять колосья",CR        DB "на зерна пшеницы.",SCRPT,35RP16    DB "С помощью чар посоха Вера разожгла костер.",SCRPT,36RP17    DB "С помощью спичек Вера разожгла костер.",SCRPT,36RP18    DB "Вера повесила чеснок на шею. Берегитесь,",CR        DB "кровопийцы!",SCRPT,41RP19    DB "Вера брызнула соком чеснока на мышь и...",SCRPT,42RP20    DB "Поморщившись, Вера смешала волчьи ягоды",CR        DB "и сушеного таракана.",ENDRP21    DB "Вылив пузырек зелья на себя, Вера тотчас",CR        DB "стала невидимой.",SCRPT,50RP22    DB "Магнит оказался настолько сильным, что",CR        DB "Зловет выронил свой железный посох.",CR        DB "Неожидав такого поворота событий, колдун",CR        DB "даже испугался.",SCRPT,52RP23    DB "При помощи свечи Вера разожгла костер.",SCRPT,36RP24    DB "С помощью колдовских чар посоха, Вера",CR        DB "уменьшила Зловета.",SCRPT,53RP25    DB "Вылив содержимое пузырька на себя, Вера",CR        DB "обрела свой прежний облик.",SCRPT,54RP26    DB "С помощью чар посоха, Вера обрела свой",CR        DB "прежний облик.",SCRPT,55RP27    DB "Вера бросила Зловета в огонь. Колдун",CR        DB "сгорел. Теперь осталось исправить",CR        DB "главную пакость.",SCRPT,57RP28    DB "Вера водрузила колокол на свое законное",CR        DB "место. Когда раздался колокольный звон,",CR        DB "все заклятия коварного Зловета с Ясной",CR        DB "поляны улетучились. Теперь с полной",CR        DB "уверенностью можно было сказать, что эта",CR        DB "история закончилась.",SCRPT,62RP29    DB "Чтобы Зловет не убежал, Вера упрятала его",CR        DB "во флакон.",ENDRP30    DB "Полеты на метле над землей сегодня",CR        DB "отменяются, - подумала Вера - грохнешься,",CR        DB "костей не соберешь. То ли дело через",CR        DB "болото, там и упасть не страшно.",ENDRP31    DB "Вера скормила огрызок козленку, на что",CR        DB "услышала смачную отрыжку в ответ.",SCRPT,64REND